function main({data1}){
  // 分割小时和分钟
  const [hours, minutes] = data1.split(':').map(Number);

  // 创建临时日期对象（自动处理跨日逻辑）
  const tempDate = new Date();
  tempDate.setHours(hours - 1, minutes, 0, 0); // 直接减1小时

  // 格式化为HH:mm并补零
  const result = [
    tempDate.getHours().toString().padStart(2, '0'),
    tempDate.getMinutes().toString().padStart(2, '0')
  ].join(':');

  return { result };
}

function main({ data1 }) {
  const [h, m] = data1.split(':').map(Number);
  const totalMinutes = h * 60 + m + 30; // 增加30分钟
  const hours = Math.floor(totalMinutes / 60) % 24; // 处理跨天
  const minutes = totalMinutes % 60;
  const result = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
  return { result };
}

