function main(input) {
    let data1 = [];
    try {
        data1 = JSON.parse(input.data1);
    } catch (error) {
        console.error("解析JSON失败:", error);
        return createEmptyResult();
    }

    if (!Array.isArray(data1)) {
        console.error("数据非数组");
        return createEmptyResult();
    }

    const weekdays = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'];
    let baseMonday = null;

    // 🔥 修复点1: 找第一个非 OFF 的有效日期作为基准
    for (const item of data1) {
        if (item.shiftDate && item.shiftCode !== 'OFF') {
            const [y, m, d] = item.shiftDate.split('-').map(Number);
            baseMonday = getWeekMonday(new Date(y, m - 1, d));
            break;
        }
    }

    // 如果全是 OFF 或无数据，回退到第一条有日期的记录
    if (!baseMonday) {
        for (const item of data1) {
            if (item.shiftDate) {
                const [y, m, d] = item.shiftDate.split('-').map(Number);
                baseMonday = getWeekMonday(new Date(y, m - 1, d));
                break;
            }
        }
    }

    // 处理每个条目的星期显示
    data1.forEach(item => {
        if (item.shiftDate && baseMonday) {
            const [y, m, d] = item.shiftDate.split('-').map(Number);
            const currentDate = new Date(y, m - 1, d);
            const currentMonday = getWeekMonday(currentDate);

            const weekDiff = Math.floor((currentMonday - baseMonday) / (1000 * 60 * 60 * 24 * 7));

            let prefix = '';
            if (weekDiff < 0) {
                // 🔥 修复点2: 支持“上”、“上上”...
                prefix = '上'.repeat(-weekDiff);
            } else if (weekDiff > 0) {
                prefix = '下'.repeat(weekDiff);
            }
            // weekDiff === 0 → 本周，无前缀

            item.datacode = prefix + weekdays[currentDate.getDay()];
        } else {
            item.datacode = '';
        }
    });

    // 分组（按 shiftDate 去重顺序）
    const seen = new Set();
    const orderedGroups = [];
    for (const item of data1) {
        if (item.shiftDate && !seen.has(item.shiftDate)) {
            seen.add(item.shiftDate);
            orderedGroups.push([item]); // 每组一个日期（即使多班次，也按原逻辑单条处理）
        }
    }

    const results = orderedGroups;
    return {
        result1: results[0] || [],
        result2: results[1] || [],
        result3: results[2] || [],
        result4: results[3] || [],
        result5: results[4] || [],
        result6: results[5] || [],
        result7: results[6] || [],
        result8: results[7] || [],
        result9: results[8] || [],
        result10: results[9] || [],
        result11: results[10] || [],
        result12: results[11] || [],
        result13: results[12] || [],
        result14: results[13] || []
    };
}

// 获取指定日期所在周的周一（本地时间，安全）
function getWeekMonday(date) {
    const d = new Date(date);
    const day = d.getDay(); // 0=Sun, 1=Mon, ..., 6=Sat
    const diff = day === 0 ? -6 : 1 - day; // 周日 → 前6天到周一，其他 → 调整到周一
    d.setDate(d.getDate() + diff);
    d.setHours(0, 0, 0, 0);
    return d;
}

