function main({ data1 }) {
  const input = data1;

  // 如果输入超过6个字，直接返回“非快捷”
  if (input.length > 6) {
    return { result: "非快捷" };
  }

  // 定义快捷指令的正则规则
  const patterns = [
    /下周|下星期|下个星期/,
    /前半天|后半天/,
    /下午|上午/,
    /提前一小时|提前1小时|推迟0\.5小时|推迟半小时|推迟1小时|推迟一小时/
  ];

  // 检查是否匹配任一规则
  const isMatched = patterns.some(p => p.test(input));

  return {
    result: isMatched ? "快捷" : "非快捷"
  };
}

